// JK02_32S settings frame 0x01; READ ONLY, never send BLE commands.
// Byte 282 bit 1 is the "Disable Temperature Sensors" setting.
// Source: syssi/esphome-jk-bms JK02_32S settings map.
const p=msg.payload||{};
if(p.type!==1||p.crc_ok!==true||typeof p.raw_hex!=="string"||
   !/^[0-9a-fA-F]{600}$/.test(p.raw_hex))return null;
const address=String(p.address||"").toUpperCase();
if(!/^[A-F0-9]{2}(:[A-F0-9]{2}){5}$/.test(address))return null;
const b=Buffer.from(p.raw_hex,"hex");
if(b.length!==300||b.subarray(0,4).toString("hex")!=="55aaeb90"||
   b[4]!==1||b.subarray(0,299).reduce((s,n)=>(s+n)&255,0)!==b[299])
  return null;
const flags=b.readUInt16LE(282);
const disabled=(flags&0x0002)!==0;
const key="temp_disable_status:"+address, now=Date.now(),last=context.get(key);
if(last&&last.disabled===disabled&&now-last.at<60000)return null;
context.set(key,{disabled,at:now});
const tail=address.slice(-5);
const result={
  address,source:"JK02_32S settings frame 0x01",
  read_only:true,raw_controls_hex:"0x"+flags.toString(16).padStart(4,"0").toUpperCase(),
  disable_temperature_sensors:disabled,
  temperature_monitoring:disabled?"DISABLED":"ENABLED",
  caution:"The BMS parameter affects thermal protection; do not change it before checking sensor wiring."
};
node.status({fill:disabled?"yellow":"blue",shape:disabled?"ring":"dot",
  text:tail+" temperature monitoring "+result.temperature_monitoring});
return {topic:"jk/"+address+"/settings/temperature_monitoring_readonly",
  payload:tail+" | Disable Temp. Sensor = "+(disabled?"ON":"OFF")+
    " | surveillance températures "+result.temperature_monitoring+
    " | reg282=0x"+flags.toString(16).padStart(4,"0").toUpperCase(),
  settings_snapshot:result};
